import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Expenses","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/caissier/depenses.md","filePath":"src/en/guide/caissier/depenses.md"}'),o={name:"en/guide/caissier/depenses.md"};function r(i,e,d,p,c,l){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="expenses" tabindex="-1">Expenses <a class="header-anchor" href="#expenses" aria-label="Permalink to &quot;Expenses&quot;">​</a></h1><p>The <strong>Expenses</strong> page lets you submit an expense request for the school — for example a purchase of supplies — and track its status until an administrator decides on it.</p><h2 id="recording-an-expense" tabindex="-1">Recording an expense <a class="header-anchor" href="#recording-an-expense" aria-label="Permalink to &quot;Recording an expense&quot;">​</a></h2><ol><li>Click <strong>New expense</strong> at the top of the <strong>Expenses</strong> page.</li><li>Choose the <strong>Site</strong> the expense relates to.</li><li>Enter the <strong>Amount</strong>.</li><li>Describe the expense in the <strong>Description</strong> field.</li><li>Click <strong>Submit request</strong>.</li></ol><p>As soon as you submit it, the school&#39;s administrators are notified automatically that an expense is waiting for their decision — there&#39;s nothing else for you to do.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Submitting an expense only records a request for approval: it doesn&#39;t debit any account and isn&#39;t tied to any particular billing record.</p></div><h2 id="tracking-an-expense-s-status" tabindex="-1">Tracking an expense&#39;s status <a class="header-anchor" href="#tracking-an-expense-s-status" aria-label="Permalink to &quot;Tracking an expense&#39;s status&quot;">​</a></h2><p>The list on the <strong>Expenses</strong> page shows, for each request, the site, the description, the amount, who requested it, and its status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Pending</td><td>The request hasn&#39;t been reviewed by an administrator yet</td></tr><tr><td>Approved</td><td>The expense was approved</td></tr><tr><td>Rejected</td><td>The expense was rejected, with a reason logged</td></tr></tbody></table><p>You can filter this list by status to quickly find a pending or already-decided expense. The decision itself (approving or rejecting) is reserved for administrator accounts — so you won&#39;t see an action button on your own requests or your colleagues&#39;.</p><p>Once an expense is <strong>approved</strong>, it automatically appears as a cash outflow in the <a href="/era-guide/en/guide/caissier/export-comptable.html">SYSCOHADA accounting export</a>.</p>',11)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
